#include <stdio.h>

int main(void) {
    int N, M;
    int G[100][100];
    int cost[2] = {0, 0};

    scanf("%d %d", &N, &M);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%d", &G[i][j]);
            int parity = (i + j) % 2;
            if ((G[i][j] % 2) != parity) cost[0]++;
            if ((G[i][j] % 2) != (1 - parity)) cost[1]++;
        }
    }

    int phase = (cost[1] < cost[0]) ? 1 : 0;
    printf("%d\n", cost[phase]);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int desired = ((i + j) % 2) ^ phase;
            int value = G[i][j];
            if ((value % 2) != desired) value++;
            printf("%d%c", value, j + 1 == M ? '\n' : ' ');
        }
    }

    return 0;
}
